const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

const SITE = process.env.SITE_URL;

/**
 * Two checks, in the order that tells you the most when one fails.
 *
 * 1. Readiness. /api/v1/health/ready answers 503 unless a checksum-verified, unexpired
 *    catalogue release loads, so this single call covers a corrupt release file, a
 *    manifest pointing at nothing, and a catalogue whose reviews have run out.
 * 2. The learner's path. Home, then into the career journey, far enough to prove the
 *    questionnaire renders and the client bundle is being served.
 *
 * The canary submits no answers to /api/v1/recommendations. Doing so every fifteen
 * minutes would put synthetic traffic through the engine and into the WAF rate counter
 * for no extra signal: if the questionnaire renders and the catalogue is ready, the
 * engine has what it needs.
 */
const checkReadiness = async function () {
  const response = await synthetics.executeHttpStep('readiness', {
    hostname: new URL(SITE).hostname,
    method: 'GET',
    path: '/api/v1/health/ready',
    protocol: 'https:'
  }, async (res) => {
    let body = '';
    res.on('data', (chunk) => { body += chunk; });
    await new Promise((resolve) => res.on('end', resolve));

    if (res.statusCode !== 200) {
      throw new Error(`Readiness returned ${res.statusCode}. Body: ${body}`);
    }
    const parsed = JSON.parse(body);
    if (parsed.status !== 'ready') {
      throw new Error(`Readiness reported ${parsed.status}: ${parsed.reason}`);
    }
    log.info(`Catalogue release ${parsed.catalogueRelease}, questionnaire ${parsed.questionnaireVersion}`);
  });
  return response;
};

const walkJourney = async function () {
  const page = await synthetics.getPage();

  await synthetics.executeStep('home', async function () {
    const response = await page.goto(SITE, { waitUntil: 'networkidle0', timeout: 30000 });
    if (!response || response.status() !== 200) {
      throw new Error(`Home returned ${response ? response.status() : 'no response'}`);
    }
    await page.waitForSelector('a[href="/guide/career"]', { timeout: 10000 });
  });

  await synthetics.executeStep('career-questionnaire', async function () {
    await page.goto(`${SITE}/guide/career`, { waitUntil: 'networkidle0', timeout: 30000 });
    // The questionnaire is client rendered, so a visible answer proves the bundle loaded
    // and hydrated, not merely that HTML came back.
    await page.waitForSelector('input[type="radio"], input[type="checkbox"]', { timeout: 15000 });
    const options = await page.$$('input[type="radio"], input[type="checkbox"]');
    if (options.length === 0) throw new Error('The first question rendered no answers.');
    log.info(`First question rendered ${options.length} answers.`);
  });

  await synthetics.executeStep('catalogue', async function () {
    const response = await page.goto(`${SITE}/courses`, { waitUntil: 'networkidle0', timeout: 30000 });
    if (!response || response.status() !== 200) {
      throw new Error(`Catalogue returned ${response ? response.status() : 'no response'}`);
    }
  });
};

exports.handler = async function () {
  if (!SITE) throw new Error('SITE_URL is not set on the canary.');
  await checkReadiness();
  await walkJourney();
  return 'ok';
};
